//! The OpenAPI document is how AI agents (and people) learn what each route
//! does, so these tests keep it complete and keep `api/openapi.json` current.
//! None of them need a database.
//!
//! After changing a route or schema, regenerate the checked-in file with
//! `make api-openapi`.

use api::app;
use api::state::AppState;
use axum::http::{Method, StatusCode};
use axum_test::TestServer;
use serde_json::Value;
use sqlx::mysql::MySqlPoolOptions;
use std::future::IntoFuture;
use std::path::{Path, PathBuf};
use std::time::Duration;

/// The spec generated by utoipa; these need `--features openapi`.
#[cfg(feature = "openapi")]
mod generated;

fn manifest_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

/// A server whose database is unreachable and fails at once: these tests
/// only need the routes.
fn server() -> TestServer {
    let pool = MySqlPoolOptions::new()
        .acquire_timeout(Duration::from_millis(50))
        .connect_lazy("mysql://unused@127.0.0.1:9/unused")
        .expect("lazy pool");
    TestServer::new(app(AppState::new(pool, "secret", "http://localhost:5173")))
}

#[tokio::test]
async fn spec_is_served_without_a_session() {
    let res = server().get("/openapi.json").await;
    res.assert_status_ok();
    let checked_in: Value = serde_json::from_str(api::openapi::CHECKED_IN).expect("openapi.json");
    assert_eq!(res.json::<Value>(), checked_in);
}

/// Without the `openapi` feature routes register from their annotations'
/// method and path alone: every operation of the checked-in spec must reach
/// a handler. axum's own misses are a 405, or a 404 with no body (a
/// handler's 404 has a JSON error).
#[tokio::test]
async fn every_documented_operation_is_routed() {
    let spec: Value = serde_json::from_str(api::openapi::CHECKED_IN).expect("openapi.json");
    let server = server();
    let mut requests = Vec::new();
    for (path, item) in spec["paths"].as_object().expect("paths") {
        let url: String = path
            .split('/')
            .map(|part| if part.starts_with('{') { "1" } else { part })
            .collect::<Vec<_>>()
            .join("/");
        for method in item.as_object().expect("path item").keys() {
            if let Ok(method) = Method::from_bytes(method.to_uppercase().as_bytes()) {
                requests.push((method, url.clone(), path.clone()));
            }
        }
    }
    let responses = futures_util::future::join_all(
        requests
            .iter()
            .map(|(method, url, _)| server.method(method.clone(), url).into_future()),
    )
    .await;
    let unrouted: Vec<String> = requests
        .iter()
        .zip(responses)
        .filter(|(_, res)| {
            let status = res.status_code();
            status == StatusCode::METHOD_NOT_ALLOWED
                || (status == StatusCode::NOT_FOUND && res.as_bytes().is_empty())
        })
        .map(|((method, _, path), _)| format!("{method} {path}"))
        .collect();
    assert!(unrouted.is_empty(), "not routed: {unrouted:?}");
}

/// A plain axum `.route(...)` would serve the endpoint but leave it out of the
/// spec; domain routers must register handlers with `routes!` instead.
#[test]
fn routes_register_through_openapi_router() {
    let mut offenders = Vec::new();
    scan_for_plain_routes(&manifest_dir().join("src/routes"), &mut offenders);
    assert!(
        offenders.is_empty(),
        "use `.routes(routes!(handler))` instead of `.route(...)` in: {offenders:?}"
    );
}

fn scan_for_plain_routes(dir: &Path, offenders: &mut Vec<PathBuf>) {
    for entry in std::fs::read_dir(dir).expect("read src/routes") {
        let path = entry.expect("dir entry").path();
        if path.is_dir() {
            scan_for_plain_routes(&path, offenders);
        } else if path.extension().is_some_and(|ext| ext == "rs")
            && std::fs::read_to_string(&path)
                .expect("read route file")
                .contains(".route(")
        {
            offenders.push(path);
        }
    }
}
